import java.io.*;

public class Main {
    static byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;
    static InputStream is = System.in;

    static int readByte() throws IOException {
        if (ptr == len) { len = is.read(buf, 0, buf.length); ptr = 0; if (len <= 0) return -1; }
        return buf[ptr++];
    }

    static String next() throws IOException {
        int c = readByte();
        while (c != -1 && c <= ' ') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') { sb.append((char) c); c = readByte(); }
        return sb.toString();
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c != '-' && (c < '0' || c > '9')) c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + (c - '0'); c = readByte(); }
        return neg ? -r : r;
    }

    public static void main(String[] args) throws IOException {
        int n = (int) nextLong(), m = (int) nextLong();
        int[] day = new int[n + 1];
        for (int i = 1; i <= n; i++) day[(int) nextLong()] = i;
        // monotonic deque: window maximum of move-in days over each length-m window
        int[] q = new int[n];
        int head = 0, tail = 0, answer = n;
        for (int i = 1; i <= n; i++) {
            while (tail > head && day[q[tail - 1]] <= day[i]) tail--;
            q[tail++] = i;
            while (tail > head && q[head] <= i - m) head++;
            if (i >= m) answer = Math.min(answer, day[q[head]]);
        }
        System.out.println(answer);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<26)
	sc.Split(bufio.ScanWords)
	nextInt := func() int {
		sc.Scan()
		v, _ := strconv.Atoi(sc.Text())
		return v
	}
	n, m := nextInt(), nextInt()
	day := make([]int, n+1)
	for i := 1; i <= n; i++ {
		day[nextInt()] = i
	}
	// monotonic deque: window maximum of move-in days over each length-m window
	q := make([]int, 0, n)
	head, answer := 0, n
	for i := 1; i <= n; i++ {
		for len(q) > head && day[q[len(q)-1]] <= day[i] {
			q = q[:len(q)-1]
		}
		q = append(q, i)
		for len(q) > head && q[head] <= i-m {
			head++
		}
		if i >= m {
			answer = min(answer, day[q[head]])
		}
	}
	fmt.Println(answer)
}
